/**
 * @file telemetry_golden.h
 * @brief The packets the V4.7.2 flight computer sends in runTelemetryScenario(), byte for byte.
 *
 * Recorded from Telemetry.cpp at 61c60ba (before the protocol moved into the shared
 * library) by running runTelemetryScenario() from telemetry_scenarios.h and printing
 * every packet it sent. The V4.7.2 wire format is the contract the ground station
 * decodes, so the flight computer must keep sending exactly these bytes.
 *
 * freq is the frequency the radio was last set to by Telemetry.cpp when the packet went
 * out (0 when FHSS is off: Telemetry.cpp never sets it then).
 */
#pragma once

#include <stdint.h>

struct GoldenPacket
{
  float freq;
  uint8_t len;
  uint8_t bytes[64];
};

